import { useQueryClient } from "@tanstack/react-query";
import { Check, ChevronDown, LogOut, Settings, Trash2, UserRound } from "lucide-react";
import { type KeyboardEvent, useEffect, useId, useState } from "react";
import { useTranslation } from "react-i18next";
import { Link } from "react-router";
import { Button } from "@/components/ui/button";
import { useChangeLanguage, useMe } from "../api/me";
import { signOutAccount } from "../auth/firebase";
import { languageNames } from "../i18n";

/**
 * The user menu of the header, named by the display name (UI-10): language, Account (WF-19),
 * Deleted Groups (WF-15), Sign out.
 */
export function UserMenu() {
  const { t, i18n } = useTranslation();
  const queryClient = useQueryClient();
  const me = useMe();
  const changeLanguage = useChangeLanguage();
  const language = me.data?.language;

  /** Every text follows the User's language: Slovenian for a new User (R-020-01, R-020-02). */
  useEffect(() => {
    if (language) void i18n.changeLanguage(language);
  }, [i18n, language]);
  const [open, setOpen] = useState(false);
  const menuId = useId();

  /** Signs out and forgets every answer of the API kept in the browser (R-001-06). */
  async function signOut() {
    setOpen(false);
    await signOutAccount();
    queryClient.clear();
  }

  function closeOnEscape(event: KeyboardEvent) {
    if (event.key === "Escape") setOpen(false);
  }

  return (
    <div className="relative min-w-0">
      <Button
        variant="ghost"
        className="max-w-full px-2 md:max-w-48 md:px-4"
        aria-expanded={open}
        aria-controls={menuId}
        onKeyDown={closeOnEscape}
        onClick={() => setOpen((value) => !value)}
      >
        <UserRound aria-hidden="true" />
        <span className="truncate">{me.data?.displayName ?? t("app.userMenu")}</span>
        <ChevronDown aria-hidden="true" />
      </Button>
      {open && (
        <ul
          id={menuId}
          className="absolute right-0 z-10 mt-1 min-w-48 rounded-md border bg-surface-raised p-1"
        >
          <li className="border-b pb-1">
            <div role="group" aria-label={t("app.language")}>
              {languageNames.map(([code, name]) => (
                <Button
                  key={code}
                  variant="ghost"
                  lang={code}
                  className="w-full justify-start"
                  aria-pressed={language === code}
                  onKeyDown={closeOnEscape}
                  onClick={() => changeLanguage.mutate(code, { onSuccess: () => setOpen(false) })}
                >
                  <Check aria-hidden="true" className={language === code ? "" : "invisible"} />
                  {name}
                </Button>
              ))}
            </div>
            {changeLanguage.isError && (
              <p role="alert" className="px-3 py-1 text-sm text-danger">
                {t("state.error")}
              </p>
            )}
          </li>
          <li className="pt-1">
            <Button asChild variant="ghost" className="w-full justify-start">
              <Link to="/account" onKeyDown={closeOnEscape} onClick={() => setOpen(false)}>
                <Settings aria-hidden="true" />
                {t("account.settings.title")}
              </Link>
            </Button>
          </li>
          <li>
            <Button asChild variant="ghost" className="w-full justify-start">
              <Link to="/deleted-groups" onKeyDown={closeOnEscape} onClick={() => setOpen(false)}>
                <Trash2 aria-hidden="true" />
                {t("deletedGroups.title")}
              </Link>
            </Button>
          </li>
          <li>
            <Button
              variant="ghost"
              className="w-full justify-start"
              onKeyDown={closeOnEscape}
              onClick={() => void signOut()}
            >
              <LogOut aria-hidden="true" />
              {t("account.signOut")}
            </Button>
          </li>
        </ul>
      )}
    </div>
  );
}

src/auth/AuthProvider.tsx.source:
import { createContext, type ReactNode, useCallback, useContext, useEffect, useState } from "react";
import { type Account, onAccountChange, refreshAccount, startAuth } from "./firebase";
import { loadRuntimeConfig } from "./runtimeConfig";

/** Where the browser stands with Firebase Authentication (ADR-03). */
export type AuthState =
  | { status: "loading" }
  | { status: "failed" }
  | { status: "signedOut" }
  | { status: "signedIn"; account: Account };

interface AuthContextValue {
  state: AuthState;
  /** Reads the account again, e.g. after the e-mail was confirmed (R-001-05). */
  refresh: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | null>(null);

let started: Promise<void> | undefined;

/** Starts Firebase once per page, from the settings of this environment (ADR-05). */
function startOnce(): Promise<void> {
  started ??= loadRuntimeConfig().then(startAuth);
  return started;
}

function stateOf(account: Account | null): AuthState {
  return account ? { status: "signedIn", account } : { status: "signedOut" };
}

/** Keeps the signed-in account for the screens (R-001-01, R-001-06). */
export function AuthProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AuthState>({ status: "loading" });

  useEffect(() => {
    let unsubscribe: (() => void) | undefined;
    let active = true;
    startOnce().then(
      () => {
        if (active) unsubscribe = onAccountChange((account) => setState(stateOf(account)));
      },
      () => setState({ status: "failed" }),
    );
    return () => {
      active = false;
      unsubscribe?.();
    };
  }, []);

  const refresh = useCallback(async () => setState(stateOf(await refreshAccount())), []);

  return <AuthContext.Provider value={{ state, refresh }}>{children}</AuthContext.Provider>;
}

/** The account state and its refresh; only inside AuthProvider. */
export function useAuth(): AuthContextValue {
  const value = useContext(AuthContext);
  if (!value) throw new Error("useAuth outside AuthProvider");
  return value;
}

src/auth/RequireAuth.tsx.source:
import type { ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { Navigate } from "react-router";
import { type AuthState, useAuth } from "./AuthProvider";
import { returnTo } from "./returnTo";

/** Loading and error states while Firebase starts (UI-14); null once the account is known. */
function Pending({ state }: { state: AuthState }) {
  const { t } = useTranslation();
  if (state.status === "loading") return <p role="status">{t("state.loading")}</p>;
  if (state.status === "failed") return <p role="alert">{t("state.error")}</p>;
  return null;
}

/** Only for a signed-in User with a confirmed e-mail (R-001-03, R-001-05, R-001-06). */
export function RequireAuth({ children }: { children: ReactNode }) {
  const { state } = useAuth();
  if (state.status === "signedOut") return <Navigate to="/sign-in" replace />;
  if (state.status !== "signedIn") return <Pending state={state} />;
  if (state.account.mustVerifyEmail) return <Navigate to="/verify-email" replace />;
  return children;
}

/**
 * Sign-in and sign-up: a signed-in User goes on to the product (R-001-01), or back to the
 * Invitation opened before signing in (R-004-07).
 */
export function GuestOnly({ children }: { children: ReactNode }) {
  const { state } = useAuth();
  if (state.status === "signedIn") {
    return <Navigate to={state.account.mustVerifyEmail ? "/verify-email" : returnTo()} replace />;
  }
  if (state.status !== "signedOut") return <Pending state={state} />;
  return children;
}

src/auth/firebase.ts.source:
import { initializeApp } from "firebase/app";
import {
  type Auth,
  connectAuthEmulator,
  createUserWithEmailAndPassword,
  getAuth,
  GoogleAuthProvider,
  onAuthStateChanged,
  sendEmailVerification,
  signInWithEmailAndPassword,
  signInWithPopup,
  signOut,
} from "firebase/auth";
import { setTokenSource } from "../api/apiClient";
import type { RuntimeConfig } from "./runtimeConfig";

/** The signed-in Firebase account as the screens need it (R-001-01, R-001-05). */
export interface Account {
  email: string | null;
  /** An e-mail/password account whose e-mail is not verified yet (R-001-05, D-16). */
  mustVerifyEmail: boolean;
}

interface FirebaseUserLike {
  email: string | null;
  emailVerified: boolean;
  providerData: { providerId: string }[];
}

let auth: Auth | undefined;

/** Starts Firebase Authentication for this environment; requests then carry its ID token. */
export function startAuth(config: RuntimeConfig): void {
  const app = initializeApp({
    apiKey: config.firebaseApiKey,
    authDomain: config.firebaseAuthDomain,
    projectId: config.firebaseProjectId,
  });
  auth = getAuth(app);
  if (config.authEmulatorUrl) {
    connectAuthEmulator(auth, config.authEmulatorUrl, { disableWarnings: true });
  }
  setTokenSource(async () => (await requireAuth().currentUser?.getIdToken()) ?? null);
}

function requireAuth(): Auth {
  if (!auth) throw new Error("Firebase Authentication is not started");
  return auth;
}

export function toAccount(user: FirebaseUserLike): Account {
  const usesPassword = user.providerData.some((p) => p.providerId === "password");
  return { email: user.email, mustVerifyEmail: usesPassword && !user.emailVerified };
}

/** Calls back with the account after every sign-in and sign-out. */
export function onAccountChange(callback: (account: Account | null) => void): () => void {
  return onAuthStateChanged(requireAuth(), (user) => callback(user ? toAccount(user) : null));
}

export async function signInWithEmail(email: string, password: string): Promise<void> {
  await signInWithEmailAndPassword(requireAuth(), email, password);
}

/** Creates the account and sends the link that confirms the e-mail (R-001-01, R-001-05). */
export async function signUpWithEmail(email: string, password: string): Promise<void> {
  const credential = await createUserWithEmailAndPassword(requireAuth(), email, password);
  await sendEmailVerification(credential.user);
}

export async function signInWithGoogle(): Promise<void> {
  await signInWithPopup(requireAuth(), new GoogleAuthProvider());
}

/** Signs out; Firebase discards the stored ID token (R-001-06). */
export async function signOutAccount(): Promise<void> {
  await signOut(requireAuth());
}

/** Reads the account again, e.g. after the e-mail was confirmed, with a fresh ID token. */
export async function refreshAccount(): Promise<Account | null> {
  const user = requireAuth().currentUser;
  if (!user) return null;
  await user.reload();
  await user.getIdToken(true);
  return toAccount(user);
}

const errorKeys = new Map<string, string | null>(
  Object.entries({
    "auth/invalid-credential": "account.error.wrongCredentials",
    "auth/invalid-login-credentials": "account.error.wrongCredentials",
    "auth/wrong-password": "account.error.wrongCredentials",
    "auth/user-not-found": "account.error.wrongCredentials",
    "auth/email-already-in-use": "account.error.emailInUse",
    "auth/invalid-email": "account.error.emailInvalid",
    "auth/weak-password": "account.error.weakPassword",
    "auth/too-many-requests": "errors.rateLimited",
    "auth/popup-closed-by-user": null,
    "auth/cancelled-popup-request": null,
  }),
);

/** The catalog key of a Firebase error; null when there is nothing to show (EX-001-01, EX-001-05). */
export function authErrorKey(error: unknown): string | null {
  const code = typeof error === "object" && error !== null && "code" in error ? error.code : "";
  const key = typeof code === "string" ? errorKeys.get(code) : undefined;
  return key === undefined ? "state.error" : key;
}

