import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "./apiClient";

/** A Group of the signed-in User with the User's Role (`Group` of the contract). */
export interface Group {
  id: string;
  name: string;
  role: "OWNER" | "EDITOR" | "VIEWER";
}

export const groupsQueryKey = ["groups"] as const;

/** The active Groups of the User, by name A–Z (R-002-03). */
export function useGroups() {
  return useQuery({
    queryKey: groupsQueryKey,
    queryFn: () => apiRequest<Group[]>("GET", "/groups"),
  });
}

/** Whether the User may change the Group's Contacts: Owner or Editor, not Viewer (BR-03). */
export function useCanChangeContacts(groupId: string): boolean {
  const role = useGroups().data?.find((group) => group.id === groupId)?.role;
  return role === "OWNER" || role === "EDITOR";
}

/** Whether the User is a Member of the Group, in any Role (BR-01). */
export function useIsMember(groupId: string): boolean {
  return useGroups().data?.some((group) => group.id === groupId) ?? false;
}

/** Whether the User is the Owner of the Group (BR-04). */
export function useIsOwner(groupId: string): boolean {
  return useGroups().data?.find((group) => group.id === groupId)?.role === "OWNER";
}

/** Creates a Group with the User as Owner (R-002-01); the Group list is read again. */
export function useCreateGroup() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (name: string) => apiRequest<Group>("POST", "/groups", { name }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: groupsQueryKey }),
  });
}

/** Renames the Group; Owner only (R-003-01); the Group list is read again. */
export function useRenameGroup(groupId: string) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (name: string) => apiRequest<Group>("PATCH", `/groups/${groupId}`, { name }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: groupsQueryKey }),
  });
}

/** Moves the Group to the recycle bin; Owner only (R-003-02); the Group list is read again. */
export function useMoveGroupToRecycleBin(groupId: string) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: () => apiRequest<undefined>("POST", `/groups/${groupId}/move-to-recycle-bin`),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: groupsQueryKey }),
  });
}

/** A Group of the User in the recycle bin (`DeletedGroup` of the contract, R-003-04). */
export interface DeletedGroup {
  id: string;
  name: string;
  deletedAt: string;
  removalAt: string;
}

const deletedGroupsQueryKey = ["deleted-groups"] as const;

/** The User's own Groups in the recycle bin, newest first (R-003-04). */
export function useDeletedGroups() {
  return useQuery({
    queryKey: deletedGroupsQueryKey,
    queryFn: () => apiRequest<DeletedGroup[]>("GET", "/deleted-groups"),
  });
}

/** Restores a Group before its removal date (R-003-05); both Group lists are read again. */
export function useRestoreGroup() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (groupId: string) =>
      apiRequest<Group>("POST", `/deleted-groups/${groupId}/restore`),
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: groupsQueryKey }),
        queryClient.invalidateQueries({ queryKey: deletedGroupsQueryKey }),
      ]),
  });
}

src/api/history.ts.source:
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { AttributeRow } from "../features/contacts/attributes";
import type { Contact } from "./contacts";
import type { ContactFields } from "../features/contacts/contactFields";
import { apiRequest } from "./apiClient";

/** One changed item of a Version (`Change` of the contract). */
export interface Change {
  item: string;
  oldValue: string | null;
  newValue: string | null;
}

/** One entry of the History (`VersionSummary` of the contract, R-010-01). */
export interface VersionSummary {
  number: number;
  kind: string;
  changedBy: string;
  changedAt: string;
  /** The Version a `restored` Version made current again (R-011-01); null for other kinds. */
  restoredFrom?: number | null;
  changes: Change[];
}

/** One Version with the content after it (`Version` of the contract, R-010-02). */
export interface Version extends VersionSummary {
  snapshot: { fields: ContactFields; attributes: AttributeRow[]; tags: string[] };
}

/** Every Version of the Contact, newest first (R-010-01). */
export function useHistory(groupId: string, contactId: string) {
  return useQuery({
    queryKey: ["groups", groupId, "contacts", contactId, "versions"],
    queryFn: () =>
      apiRequest<VersionSummary[]>("GET", `/groups/${groupId}/contacts/${contactId}/versions`),
  });
}

/** Version `number` of the Contact with the content after it (R-010-02). */
export function useVersion(groupId: string, contactId: string, number: string) {
  return useQuery({
    queryKey: ["groups", groupId, "contacts", contactId, "versions", number],
    queryFn: () =>
      apiRequest<Version>("GET", `/groups/${groupId}/contacts/${contactId}/versions/${number}`),
  });
}

/**
 * Makes Version `number` current as a new Version `restored`, sent with the current Version number
 * read (R-011-01, BR-06). The restored Contact replaces the one read; its History and the lists
 * are read again.
 */
export function useRestoreVersion(groupId: string, contactId: string, number: string) {
  const queryClient = useQueryClient();
  const contactKey = ["groups", groupId, "contacts", contactId];
  return useMutation({
    mutationFn: (read: Contact) =>
      apiRequest<Contact>(
        "POST",
        `/groups/${groupId}/contacts/${contactId}/versions/${number}/restore`,
        { versionNumber: read.versionNumber },
      ),
    onSuccess: async (restored) => {
      queryClient.setQueryData(contactKey, restored);
      await queryClient.invalidateQueries({ queryKey: [...contactKey, "versions"] });
      await queryClient.invalidateQueries({ queryKey: ["groups", groupId, "contacts", "list"] });
    },
    onError: () => queryClient.invalidateQueries({ queryKey: contactKey, exact: true }),
  });
}

