import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { createMemoryRouter, RouterProvider } from "react-router";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { apiRequest } from "../../api/apiClient";
import { ApiError } from "../../api/problem";
import i18n from "../../i18n";
import { DeletedGroupsPage } from "./DeletedGroupsPage";

vi.mock("../../api/apiClient", () => ({ apiRequest: vi.fn() }));

const KONFERENCA = {
  id: "g1",
  name: "Konferenca 2025",
  deletedAt: "2026-03-05T10:00:00Z",
  removalAt: "2026-04-04T10:00:00Z",
};

/** GET answers the given deleted Groups (and the Groups); POST the restored Group. */
function answer(deleted: unknown[]) {
  vi.mocked(apiRequest).mockImplementation((method: string, path: string) => {
    if (method === "GET") return Promise.resolve(path === "/deleted-groups" ? deleted : []);
    return Promise.resolve({ id: "g1", name: "Konferenca 2025", role: "OWNER" });
  });
}

function renderPage() {
  const router = createMemoryRouter(
    [
      { path: "/deleted-groups", element: <DeletedGroupsPage /> },
      { path: "/groups/:groupId/contacts", element: <p>contact list</p> },
    ],
    { initialEntries: ["/deleted-groups"] },
  );
  render(
    <QueryClientProvider
      client={new QueryClient({ defaultOptions: { queries: { retry: false } } })}
    >
      <RouterProvider router={router} />
    </QueryClientProvider>,
  );
  return router;
}

beforeEach(async () => {
  vi.mocked(apiRequest).mockReset();
  answer([KONFERENCA]);
  await i18n.changeLanguage("en");
});
afterEach(async () => {
  await i18n.changeLanguage("sl");
});

describe("WF-15 Deleted Groups (US-003)", () => {
  it("AC-003-03 lists the name and the removal date in Europe/Ljubljana", async () => {
    renderPage();

    expect(await screen.findByRole("heading", { level: 1, name: "Deleted Groups" })).toBeTruthy();
    expect(apiRequest).toHaveBeenCalledWith("GET", "/deleted-groups");
    const row = await screen.findByRole("row", { name: /Konferenca 2025/ });
    expect(row.textContent).toContain("04.04.2026 12:00");
  });

  it("AC-003-04 Restore restores the Group and opens its Contact list", async () => {
    const router = renderPage();
    const row = await screen.findByRole("row", { name: /Konferenca 2025/ });

    await userEvent.click(within(row).getByRole("button", { name: "Restore" }));

    expect(apiRequest).toHaveBeenCalledWith("POST", "/deleted-groups/g1/restore");
    await waitFor(() => expect(router.state.location.pathname).toBe("/groups/g1/contacts"));
  });

  it("R-003-06 a refused restore: This Group can no longer be restored.", async () => {
    renderPage();
    const row = await screen.findByRole("row", { name: /Konferenca 2025/ });
    vi.mocked(apiRequest).mockImplementation((method: string) =>
      method === "POST"
        ? Promise.reject(new ApiError(409, { code: "group.noLongerRestorable" }))
        : Promise.resolve([KONFERENCA]),
    );

    await userEvent.click(within(row).getByRole("button", { name: "Restore" }));

    expect((await screen.findByRole("alert")).textContent).toBe(
      "This Group can no longer be restored.",
    );
  });

  it("UI-14 no deleted Groups: No deleted Groups.", async () => {
    answer([]);
    renderPage();

    expect(await screen.findByText("No deleted Groups.")).toBeTruthy();
  });
});

src/features/export/ExportButtons.test.t.source:
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { apiDownload } from "../../api/apiClient";
import { ApiError } from "../../api/problem";
import i18n from "../../i18n";
import { type ListQuery, NO_FILTERS } from "../contacts/listQuery";
import { ExportButtons } from "./ExportButtons";

vi.mock("../../api/apiClient", () => ({ apiDownload: vi.fn() }));

const QUERY: ListQuery = {
  q: "novak",
  sort: "company",
  dir: "desc",
  page: 2,
  filters: { ...NO_FILTERS, hasTagIds: ["t1"], country: "SI" },
};
const FILE = { blob: new Blob(["PK"]), fileName: "kontakti-Konferenca 2025-2026-03-05.xlsx" };

function renderButtons(total: number, checked: string[] = []) {
  render(
    <QueryClientProvider client={new QueryClient()}>
      <ExportButtons groupId="g1" query={QUERY} total={total} checked={checked} />
    </QueryClientProvider>,
  );
}

let saved: string[];

beforeEach(async () => {
  vi.mocked(apiDownload).mockReset();
  saved = [];
  vi.stubGlobal("URL", { ...URL, createObjectURL: () => "blob:x", revokeObjectURL: () => {} });
  vi.spyOn(HTMLAnchorElement.prototype, "click").mockImplementation(function (
    this: HTMLAnchorElement,
  ) {
    saved.push(this.download);
  });
  await i18n.changeLanguage("en");
});
afterEach(async () => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
  await i18n.changeLanguage("sl");
});

const exportButton = () => screen.getByRole("button", { name: "Export" });

describe("Export buttons of WF-06 (US-016)", () => {
  it("AC-016-01 Export sends the list query and saves the file with its name", async () => {
    vi.mocked(apiDownload).mockResolvedValue(FILE);
    renderButtons(2);

    await userEvent.click(exportButton());

    await waitFor(() => expect(saved).toEqual([FILE.fileName]));
    expect(apiDownload).toHaveBeenCalledWith("/groups/g1/exports", {
      q: "novak",
      sort: "company",
      dir: "desc",
      ...NO_FILTERS,
      hasTagIds: ["t1"],
      country: "SI",
    });
  });

  it("AC-016-02 Export checked sends only the Checked contacts", async () => {
    vi.mocked(apiDownload).mockResolvedValue(FILE);
    renderButtons(3, ["c3"]);

    expect(screen.getByText("1 checked")).toBeTruthy();
    await userEvent.click(screen.getByRole("button", { name: "Export checked (1)" }));

    await waitFor(() => expect(saved).toEqual([FILE.fileName]));
    expect(vi.mocked(apiDownload).mock.calls[0]?.[1]).toMatchObject({ contactIds: ["c3"] });
  });

  it("R-016-02 Export checked is disabled while no Contact is checked", () => {
    renderButtons(3);

    expect(screen.getByRole("button", { name: "Export checked" }).hasAttribute("disabled")).toBe(
      true,
    );
    expect(screen.queryByText(/^\d+ checked$/)).toBeNull();
  });

  it("R-016-07 EX-016-02 an empty scope disables Export: Nothing to export.", () => {
    renderButtons(0);

    expect(exportButton().hasAttribute("disabled")).toBe(true);
    expect(screen.getByText("Nothing to export.")).toBeTruthy();
  });

  it("R-016-05 AC-016-03 more than 10,000 Contacts: Export disabled with the message", () => {
    renderButtons(10_001);

    expect(exportButton().hasAttribute("disabled")).toBe(true);
    expect(screen.getByText("Narrow the list to at most 10,000 Contacts to export.")).toBeTruthy();
  });

  it("EX-016-01 exactly 10,000 Contacts can be exported", () => {
    renderButtons(10_000);

    expect(exportButton().hasAttribute("disabled")).toBe(false);
  });

  it("R-016-05 a refused Export shows the message of the problem and saves nothing", async () => {
    vi.mocked(apiDownload).mockRejectedValue(new ApiError(409, { code: "export.tooMany" }));
    renderButtons(2);

    await userEvent.click(exportButton());

    expect((await screen.findByRole("alert")).textContent).toBe(
      "Narrow the list to at most 10,000 Contacts to export.",
    );
    expect(saved).toEqual([]);
  });

  it("UI-12 both buttons are disabled while the file is made", async () => {
    vi.mocked(apiDownload).mockReturnValue(new Promise(() => {}));
    renderButtons(2, ["c1"]);

    await userEvent.click(exportButton());

    await waitFor(() => expect(exportButton().hasAttribute("disabled")).toBe(true));
    expect(
      screen.getByRole("button", { name: "Export checked (1)" }).hasAttribute("disabled"),
    ).toBe(true);
  });
});

